{"ok": true, "path": "server/routes/sync.js", "content": "1: const express = require('express');
2: const { openDb } = require('../db');
3: const { authMiddleware } = require('../middleware/auth');
4: 
5: const router = express.Router();
6: 
7: // 全部业务端点需要认证
8: router.use(authMiddleware);
9: 
10: const VALID_RESOURCES = ['customDishes', 'ratings', 'todayMenu', 'guestCart'];
11: 
12: /**
13:  * GET /api/sync
14:  * 返回当前用户的所有四类同步数据
15:  */
16: router.get('/', (req, res) => {
17:   try {
18:     const db = openDb();
19:     const rows = db.prepare(
20:       'SELECT resource, data_json, version, updated_at FROM user_sync WHERE user_id = ?'
21:     ).all(req.user.id);
22: 
23:     const result = {};
24:     for (const r of rows) {
25:       try {
26:         result[r.resource] = JSON.parse(r.data_json);
27:       } catch {
28:         result[r.resource] = (r.resource === 'ratings' ? {} : []);
29:       }
30:     }
31: 
32:     // 为未初始化的资源返回默认值
33:     for (const r of VALID_RESOURCES) {
34:       if (!(r in result)) {
35:         result[r] = (r === 'ratings' ? {} : []);
36:       }
37:     }
38: 
39:     res.json(result);
40:   } catch (err) {
41:     console.error('sync get error:', err);
42:     res.status(500).json({ error: 'Internal server error' });
43:   }
44: });
45: 
46: /**
47:  * PUT /api/sync/:resource
48:  * 幂等替换式同步：全量替换指定资源
49:  *
50:  * customDishes: 菜品对象数组 (同自定义菜品结构)
51:  * ratings: { dishName: stars, ... }
52:  * todayMenu: string[]
53:  * guestCart: string[]
54:  */
55: router.put('/:resource', (req, res) => {
56:   try {
57:     const { resource } = req.params;
58:     if (!VALID_RESOURCES.includes(resource)) {
59:       return res.status(400).json({ error: `Invalid resource. Must be one of: ${VALID_RESOURCES.join(', ')}` });
60:     }
61: 
62:     const data = req.body;
63: 
64:     // 校验数据类型
65:     if (resource === 'ratings') {
66:       if (typeof data !== 'object' || data === null || Array.isArray(data)) {
67:         return res.status(400).json({ error: 'ratings must be a JSON object { dishName: stars }' });
68:       }
69:       // 验证值都是数字
70:       for (const [k, v] of Object.entries(data)) {
71:         if (typeof v !== 'number' || v < 0 || v > 5) {
72:           return res.status(400).json({ error: `ratings.${k} must be a number 0-5` });
73:         }
74:       }
75:     } else {
76:       if (!Array.isArray(data)) {
77:         return res.status(400).json({ error: `${resource} must be a JSON array` });
78:       }
79:       if (resource === 'customDishes') {
80:         for (const d of data) {
81:           if (!d.name || typeof d.name !== 'string') {
82:             return res.status(400).json({ error: 'Each custom dish must have a string name' });
83:           }
84:         }
85:       } else {
86:         // todayMenu / guestCart: string arrays
87:         for (const item of data) {
88:           if (typeof item !== 'string') {
89:             return res.status(400).json({ error: `${resource} items must be strings` });
90:           }
91:         }
92:       }
93:     }
94: 
95:     const db = openDb();
96:     const dataJson = JSON.stringify(data);
97: 
98:     const existing = db.prepare(
99:       'SELECT version FROM user_sync WHERE user_id = ? AND resource = ?'
100:     ).get(req.user.id, resource);
101: 
102:     if (existing) {
103:       db.prepare(
104:         `UPDATE user_sync SET data_json = ?, version = version + 1, updated_at = datetime('now')
105:          WHERE user_id = ? AND resource = ?`
106:       ).run(dataJson, req.user.id, resource);
107:     } else {
108:       db.prepare(
109:         'INSERT INTO user_sync (user_id, resource, data_json) VALUES (?, ?, ?)'
110:       ).run(req.user.id, resource, dataJson);
111:     }
112: 
113:     const updated = db.prepare(
114:       'SELECT resource, version, updated_at FROM user_sync WHERE user_id = ? AND resource = ?'
115:     ).get(req.user.id, resource);
116: 
117:     res.json({
118:       resource,
119:       version: updated.version,
120:       updated_at: updated.updated_at
121:     });
122:   } catch (err) {
123:     console.error('sync put error:', err);
124:     res.status(500).json({ error: 'Internal server error' });
125:   }
126: });
127: 
128: module.exports = router;", "total_lines": 128}

